#include <vector>
#include <cstddef>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    const std::size_t n = x.size();
    double result = 1.0;

    #pragma omp parallel
    {
        double local_even_prod = 1.0; // product of x[i] for even i
        double local_odd_prod  = 1.0; // product of x[i] for odd i

        #pragma omp for nowait
        for (std::size_t i = 0; i < n; ++i) {
            if ((i & 1u) == 0u) {
                local_even_prod *= x[i];
            } else {
                local_odd_prod *= x[i];
            }
        }

        const double local_factor = local_even_prod / local_odd_prod;

        #pragma omp critical
        {
            result *= local_factor;
        }
    }

    return result;
}
